import{_ as a,o as e,c as i,ai as r}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"[决策] V0 为何 Gateway → HTTP → Spring Boot","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/industrial-digitalization/decisions/01-v0-gateway-http.md","filePath":"tech-system/industrial-digitalization/decisions/01-v0-gateway-http.md"}'),d={name:"tech-system/industrial-digitalization/decisions/01-v0-gateway-http.md"};function s(n,t,o,l,h,c){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="决策-v0-为何-gateway-→-http-→-spring-boot" tabindex="-1"><code>[决策]</code> V0 为何 Gateway → HTTP → Spring Boot <a class="header-anchor" href="#决策-v0-为何-gateway-→-http-→-spring-boot" aria-label="Permalink to “[决策] V0 为何 Gateway → HTTP → Spring Boot”">​</a></h1><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>状态</td><td>🔵 设计中</td></tr><tr><td>类型</td><td><code>[决策]</code></td></tr><tr><td>项目</td><td>Mini MES V0</td></tr><tr><td>证据</td><td>待 Lab 001</td></tr><tr><td>GitHub</td><td>暂未开放</td></tr></tbody></table><hr><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>需要先跑通：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设备（模拟）→ 采集 → 后端 → 监控页</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>目标是<strong>证明链</strong>，不是协议博物馆。</p><h2 id="候选" tabindex="-1">候选 <a class="header-anchor" href="#候选" aria-label="Permalink to “候选”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>含义</th></tr></thead><tbody><tr><td>A</td><td>Java 业务服务直接连 Modbus/S7</td></tr><tr><td>B</td><td>Gateway 采集后 HTTP 推到 Spring Boot</td></tr><tr><td>C</td><td>Gateway → MQTT → 后端（直接上 V1）</td></tr></tbody></table><h2 id="判断" tabindex="-1">判断 <a class="header-anchor" href="#判断" aria-label="Permalink to “判断”">​</a></h2><p>选 <strong>B</strong>。</p><ol><li><strong>协议与业务隔离</strong>：Gateway 懂寄存器；Spring Boot 懂设备档案、告警、展示。</li><li><strong>HTTP 对单生产者→单消费者足够</strong>：调试用 curl/日志即可，心智负担低。</li><li><strong>不选 A</strong>：业务进程绑死协议与重连逻辑，后面加第二种协议或第二个消费者会痛。</li><li><strong>不选 C（现在）</strong>：消息中间件的收益在多订阅方与解耦；V0 还没有第二个消费者，复杂度大于收益。见 <a href="./02-no-mqtt-yet.html">02</a>。</li></ol><h2 id="适用-不适用" tabindex="-1">适用 / 不适用 <a class="header-anchor" href="#适用-不适用" aria-label="Permalink to “适用 / 不适用”">​</a></h2><ul><li>✅ 实验室 V0、单 Gateway、单后端、要快速看见数据</li><li>❌ 多网关、多分析消费者、强离线缓冲——那时评估 MQTT</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h2><p>V0：<code>Gateway → HTTP → Spring Boot</code>。演进本身会变成下一篇对照决策。</p><h2 id="验证计划" tabindex="-1">验证计划 <a class="header-anchor" href="#验证计划" aria-label="Permalink to “验证计划”">​</a></h2><p>Lab 001 跑通后：本页状态 → 🟢；补充 QPS、失败率与截图链接。</p>',18)])])}const g=a(d,[["render",s]]);export{b as __pageData,g as default};
